// Order-18 IIR, TRANSPOSED feedforward chain: one multiply+add per stage
// (registered partial sums) + a tiny feedback stage -> critical path roughly
// independent of the order -> high Fmax. Same transfer function.
module iir18_v7 (
  input clk, input rst_n, input [7:0] x, output reg [15:0] y
);
  reg [15:0] r1;
  reg [15:0] r2;
  reg [15:0] r3;
  reg [15:0] r4;
  reg [15:0] r5;
  reg [15:0] r6;
  reg [15:0] r7;
  reg [15:0] r8;
  reg [15:0] r9;
  reg [15:0] r10;
  reg [15:0] r11;
  reg [15:0] r12;
  reg [15:0] r13;
  reg [15:0] r14;
  reg [15:0] r15;
  reg [15:0] r16;
  reg [15:0] r17;
  reg [15:0] r18;
  reg [15:0] y2;
  reg [15:0] y3;
  always @(posedge clk) begin
    if (!rst_n) begin y<=0; y2<=0; y3<=0; r1<=0; r2<=0; r3<=0; r4<=0; r5<=0; r6<=0; r7<=0; r8<=0; r9<=0; r10<=0; r11<=0; r12<=0; r13<=0; r14<=0; r15<=0; r16<=0; r17<=0; r18<=0; end
    else begin
      y <= ((25*x + r1 + ((9*y)>>4) + ((5*y2)>>4)) & 16'hFFFF);
      y2 <= ((26*x + r2 + y) & 16'hFFFF);
      y3 <= ((46*x + r3 + y2) & 16'hFFFF);
      r4 <= ((49*x + r4 + y3) & 16'hFFFF);
      r5 <= ((16*x + r5 + r4) & 16'hFFFF);
      r6 <= ((8*x + r6 + r5) & 16'hFFFF);
      r7 <= ((15*x + r7 + r6) & 16'hFFFF);
      r8 <= ((31*x + r8 + r7) & 16'hFFFF);
      r9 <= ((37*x + r9 + r8) & 16'hFFFF);
      r10 <= ((52*x + r10 + r9) & 16'hFFFF);
      r11 <= ((6*x + r11 + r10) & 16'hFFFF);
      r12 <= ((54*x + r12 + r11) & 16'hFFFF);
      r13 <= ((60*x + r13 + r12) & 16'hFFFF);
      r14 <= ((33*x + r14 + r13) & 16'hFFFF);
      r15 <= ((33*x + r15 + r14) & 16'hFFFF);
      r16 <= ((62*x + r16 + r15) & 16'hFFFF);
      r17 <= ((48*x + r17 + r16) & 16'hFFFF);
      r18 <= ((18*x + r18 + r17) & 16'hFFFF);
      r1 <= ((56*x + r1 + r18) & 16'hFFFF);
    end
  end
endmodule
